// Actual SaveStore/CloudSync/CommunityStats; generated identities and fake HTTP only.
using System;using System.IO;using System.Linq;using System.Collections;using System.Reflection;using System.Collections.Generic;using ReversalTower;using UnityEngine;using UnityEngine.Networking;
public static class ProficiencyHttpTests {
 static int n;static void Check(bool x,string name){if(!x)throw new Exception(name);n++;Console.WriteLine("PASS "+name);}static void Drain(IEnumerator e){while(e.MoveNext())if(e.Current is IEnumerator c)Drain(c);}
 static TutorialAssessment Assessment(bool first=true)=>new TutorialAssessment{completed=true,valid=true,isFirstAssessment=first,group="expert",score=.95f,confidence=.75f,activeDurationSeconds=60,elapsedDurationSeconds=80,ultimateExecutionSuccess=true,parryAttempts=3,parrySuccesses=3,dodgeAttempts=3,dodgeSuccesses=3,completedAtUtc=first?"2026-11-18T01:00:00Z":"2026-11-18T02:00:00Z"};
 static IEnumerator Call(CloudSync c,string method)=>(IEnumerator)typeof(CloudSync).GetMethod(method,BindingFlags.NonPublic|BindingFlags.Instance).Invoke(c,null);
 static void Field(CloudSync c,string k,object v)=>typeof(CloudSync).GetField(k,BindingFlags.NonPublic|BindingFlags.Instance).SetValue(c,v);
 public static int Main(){string root=Path.Combine(Path.GetTempPath(),"proficiency-http-"+Guid.NewGuid().ToString("N"));SaveStore.UseIsolatedRoot(root);
 try{
 var save=new SaveData{tutorialAssessment=Assessment()};Check(SaveStore.Save(save),"local assessment safely saved before telemetry");var files=Directory.GetFiles(SaveStore.ProficiencyQueueRoot,"*.json");Check(files.Length==1,"first real assessment enqueued");string secret;var e=SaveStore.ReadProficiency(files[0],out secret);Check(secret.Length==64&&!File.ReadAllText(files[0]).Contains(secret)&&e.ownerKey.Length==64,"capability stays outside save and queue");Check(!File.ReadAllText(Path.Combine(root,"progress.json")).Contains(secret),"progress excludes capability");
 SaveStore.QueueAssessments(save);Check(Directory.GetFiles(SaveStore.ProficiencyQueueRoot,"*.json").Length==1,"stable assessment event suppresses duplicate enqueue");
 save.tutorialReplayAssessment=Assessment(false);Check(SaveStore.Save(save),"reassessment saves independently");Check(save.tutorialAssessment.isFirstAssessment&&save.tutorialAssessment.completedAtUtc!=save.tutorialReplayAssessment.completedAtUtc,"replay cannot overwrite initial evidence");
 var battle=new HistoryEntry{battleId=Guid.NewGuid().ToString(),boss="arakus",seconds=60};SaveStore.QueueProficiencyBattle(save,battle,new List<PatternStats>{new PatternStats{id="cleave",level=0,opportunities=20,parries=20}});
 var be=Directory.GetFiles(SaveStore.ProficiencyQueueRoot,"*.json").Select(f=>SaveStore.ReadProficiency(f,out var k)).Single(x=>x.kind=="battle");Check(be.assessmentId==SaveStore.AssessmentEventId(save.cloudPlayerId,save.tutorialAssessment),"battle captures first assessment not replay");
 var cloud=new CloudSync();var cfg=Activator.CreateInstance(typeof(CloudSync).GetNestedType("Config",BindingFlags.NonPublic),true);cfg.GetType().GetField("url").SetValue(cfg,"https://invalid.local");cfg.GetType().GetField("anonKey").SetValue(cfg,"mock");cfg.GetType().GetField("proficiencySync").SetValue(cfg,true);Field(cloud,"config",cfg);Field(cloud,"playerId",save.cloudPlayerId);
 UnityWebRequest.Respond=u=>(UnityWebRequest.Result.ConnectionError,503,"offline");Drain(Call(cloud,"SyncProficiency"));Check(Directory.GetFiles(SaveStore.ProficiencyQueueRoot,"*.json").Length==3,"HTTP failure retains every pending immutable event");
 UnityWebRequest.Respond=u=>(UnityWebRequest.Result.ConnectionError,409,"conflict");Drain(Call(cloud,"SyncProficiency"));Check(Directory.GetFiles(SaveStore.ProficiencyQueueRoot,"*.json").Length==3,"409 never blindly acknowledges protected data");
 UnityWebRequest.Respond=u=>(UnityWebRequest.Result.Success,200,"false");Drain(Call(cloud,"SyncProficiency"));Check(Directory.GetFiles(SaveStore.ProficiencyQueueRoot,"*.json").Length==3,"false RPC result is not accepted");
 UnityWebRequest.Requests.Clear();UnityWebRequest.Respond=u=>(UnityWebRequest.Result.Success,200,"true");Drain(Call(cloud,"SyncProficiency"));Check(!Directory.GetFiles(SaveStore.ProficiencyQueueRoot,"*.json").Any(),"successful true RPC creates receipts and acknowledges");var posts=UnityWebRequest.Requests;Check(posts.Count==3&&posts.Take(2).All(p=>p.body.Contains("\"p_kind\":\"assessment\""))&&posts.Last().body.Contains("\"p_kind\":\"battle\""),"assessments sent before linked battles");Check(posts.All(p=>p.body.Contains(secret)&&p.body.Contains(save.cloudPlayerId)),"actual RPC binds captured owner capability and profile");SaveStore.QueueAssessments(save);Check(!Directory.GetFiles(SaveStore.ProficiencyQueueRoot,"*.json").Any(),"receipts suppress restart duplicate without editing assessment");
 var other=new SaveData{tutorialAssessment=Assessment()};SaveStore.Save(other);var otherFile=Directory.GetFiles(SaveStore.ProficiencyQueueRoot,"*.json").Single();var oe=SaveStore.ReadProficiency(otherFile,out var otherSecret);Check(oe.profile!=e.profile&&otherSecret!=secret,"new profile gets independent ownership capability");
 File.Delete(Path.Combine(root,"ProficiencyKeys",other.cloudPlayerId+".key"));UnityWebRequest.Requests.Clear();Drain(Call(cloud,"SyncProficiency"));Check(File.Exists(otherFile)&&UnityWebRequest.Requests.Count==0,"missing original key preserves queue without sending under new owner");other.tutorialReplayAssessment=Assessment(false);SaveStore.Save(other);Check(!File.Exists(Path.Combine(root,"ProficiencyKeys",other.cloudPlayerId+".key")),"new events cannot silently regenerate lost profile key");
 CommunityStats.ReplaceGroups(new CommunityStats.Entry[0]);UnityWebRequest.Respond=u=>(UnityWebRequest.Result.Success,200,"[{\"boss\":\"arakus\",\"pattern\":\"cleave\",\"group_name\":\"expert\",\"players\":3,\"opportunities\":20,\"success_rate\":0.95,\"suggested_level\":1}]");var fetch=Call(cloud,"FetchGroups");Check(fetch.MoveNext()&&CommunityStats.GroupState=="수신 중","group request can suspend without blocking first battle");var pending=new DdaBattleSession();pending.Prepare(save,Catalog.Bosses[0],false);Check(pending.Stats[0].level==1&&pending.Sources["cleave"]=="튜토리얼","pending group uses valid tutorial fallback immediately");Drain(fetch);var ready=new DdaBattleSession();ready.Prepare(save,Catalog.Bosses[0],false);Check(ready.Sources["cleave"]=="그룹 DB"&&CommunityStats.GroupOrigin=="HTTP 수신","actual HTTP group row reaches actual Prepare");long revision=CommunityStats.Revision;UnityWebRequest.Respond=u=>(UnityWebRequest.Result.Success,200,"[null]");Drain(Call(cloud,"FetchGroups"));Check(CommunityStats.Revision==revision,"malformed group response preserves previous snapshot");UnityWebRequest.Respond=u=>(UnityWebRequest.Result.ConnectionError,503,"");Drain(Call(cloud,"FetchGroups"));Check(CommunityStats.Revision==revision,"group network failure preserves prior snapshot");
 var cancelled=Call(cloud,"FetchGroups");cancelled.MoveNext();((IDisposable)cancelled).Dispose();Check(CommunityStats.GroupState=="수신 중단","cancelled group receive cannot remain pending forever");
 var cp=new HistoryEntry{battleId=Guid.NewGuid().ToString(),boss="arakus",seconds=60};save.history.Add(cp);Check(SaveStore.CommitCompletedBattle(save,cp),"assessment profile archived by actual completed battle commit");SaveStore.QueueProficiencyBattle(save,cp,new List<PatternStats>());string originalFile=Directory.GetFiles(SaveStore.ProficiencyQueueRoot,save.cloudPlayerId+"_*.json").Single();SaveData reset,restored;Check(SaveStore.TryResetProfile(save,false,out reset)&&reset.cloudPlayerId!=save.cloudPlayerId,"actual reset creates fresh profile without reassigning pending telemetry");Check(SaveStore.TryRestoreProfile(reset,cp.snapshotId,false,out restored)&&restored.cloudPlayerId==save.cloudPlayerId&&restored.tutorialAssessment.isFirstAssessment,"actual restore recovers original UUID and first assessment");var oldEnvelope=SaveStore.ReadProficiency(originalFile,out var restoredSecret);Check(restoredSecret==secret&&oldEnvelope.profile==save.cloudPlayerId,"restored profile retains original capability and immutable queued owner");
 Console.WriteLine("PROFICIENCY_HTTP_PASS "+n);return 0;
 }finally{UnityWebRequest.Respond=null;SaveStore.UseIsolatedRoot(null);Directory.Delete(root,true);}}
}
